@dataclass(frozen=True)
class Params:
    time: TimeParams = field(default_factory=TimeParams)
    labels: LabelsParams = field(default_factory=LabelsParams)
    vectors: VectorsParams = field(default_factory=VectorsParams)
    ties: TiesParams = field(default_factory=TiesParams)
    factions: FactionsParams = field(default_factory=FactionsParams)
    capital: CapitalParams = field(default_factory=CapitalParams)
    influencers: InfluencersParams = field(default_factory=InfluencersParams)
    community: CommunityParams = field(default_factory=CommunityParams)
    economy: EconomyParams = field(default_factory=EconomyParams)
    pillars: PillarsParams = field(default_factory=PillarsParams)
    threats: ThreatsParams = field(default_factory=ThreatsParams)
    events: EventsParams = field(default_factory=EventsParams)
    demography: DemographyParams = field(default_factory=DemographyParams)
    technical: TechnicalParams = field(default_factory=TechnicalParams)

    def with_overrides(self, overrides: dict[str, Any]) -> Params:
        """New Params with raw parameters replaced; derived ones are recomputed."""
        flat = to_flat(self, include_derived=False)
        for k, v in overrides.items():
            if k not in flat:
                raise KeyError(f"unknown or derived parameter '{k}'")
            flat[k] = v
        return from_flat(flat)


