DERIVED = ('theta_stab_out', 'rho_out', 'N_min', 'theta_m_out', 'g_0', 'g_inf', 'theta_y_out', 'g_T')

FORMULAS = {
    'theta_stab_out': '0.625 * theta_stab_in',
    'rho_out': 'rho_in * 22.0 / 15.0',
    'N_min': 'max(5, ceil(0.02 * N))',
    'theta_m_out': '0.5 * theta_m_in',
    'g_0': 'income_for_equilibrium(h_K, x_star_K)',
    'g_inf': 'income_for_equilibrium(h_inf, x_star_inf)',
    'theta_y_out': '0.5 * theta_y_in',
    'g_T': 'income_for_equilibrium(h_pT, x_star_T)',
}
INT_PARAMS = ('N', 'horizon_days', 'T_warm', 'B_bond', 'bounded_confidence', 'routine_partners', 'N_min', 'n_council', 'n_cust', 'K_opt', 'n_news_0', 'n_log', 'a_adult', 'a_pens', 'a_fert', 'delta_a_couple', 'n_lab', 'n_retry', 'B_gen', 'B_S1', 'panel_every')


def to_flat(p: Params, include_derived: bool = True) -> dict[str, Any]:
    out: dict[str, Any] = {}
    for g in fields(p):
        grp = getattr(p, g.name)
        for f in fields(grp):
            if include_derived or f.name not in DERIVED:
                out[f.name] = getattr(grp, f.name)
    return out


def _resolve_derived(flat: dict[str, Any]) -> dict[str, Any]:
    pending = list(DERIVED)
    for _ in range(len(pending) + 1):
        left = []
        for k in pending:
            try:
                v = eval(FORMULAS[k], {"__builtins__": {}}, {**FORMULA_NAMESPACE, **flat})  # noqa: S307
            except NameError:
                left.append(k)
                continue
            flat[k] = int(v) if k in INT_PARAMS else float(v)
        pending = left
        if not pending:
            break
    return flat


def from_flat(values: dict[str, Any]) -> Params:
    """Build Params from raw values (missing ones take registry defaults) and recompute derived ones."""
    base = to_flat(Params())
    for k, v in values.items():
        if k not in base:
            raise KeyError(f"unknown parameter '{k}'")
        if k in DERIVED and v != base[k]:
            # derived values are accepted only if they equal what the formulas produce
            continue
        base[k] = int(v) if k in INT_PARAMS else float(v)
    base = _resolve_derived(base)
    kwargs = {}
    for g in fields(Params):
        cls = Params.__dataclass_fields__[g.name].default_factory  # type: ignore[misc]
        kwargs[g.name] = cls(**{f.name: base[f.name] for f in fields(cls)})
    return Params(**kwargs)


def default_params() -> Params:
    """Registry defaults with every derived parameter recomputed from its formula."""
    return from_flat({})

